CREATE TABLE `usuarios` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `nome` varchar(160) NOT NULL,
  `cnpj` varchar(20) NOT NULL,
  `email` varchar(160) NOT NULL,
  `senha` varchar(255) NOT NULL,
  `area` varchar(60) NOT NULL,
  `status` enum('pendente','aprovada','recusada','suspensa') NOT NULL DEFAULT 'pendente',
  `aprovado_em` datetime DEFAULT NULL,
  `verificada_em` datetime DEFAULT NULL,
  `verificado_por` int(10) unsigned DEFAULT NULL,
  `motivo_recusa` text DEFAULT NULL,
  `responsavel_nome` varchar(160) NOT NULL DEFAULT '',
  `responsavel_cargo` varchar(80) NOT NULL DEFAULT '',
  `responsavel_autorizacao` tinyint(1) NOT NULL DEFAULT 0,
  `canal_tipo` enum('site','instagram','facebook','telefone','outro') NOT NULL DEFAULT 'site',
  `canal_valor` varchar(255) NOT NULL DEFAULT '',
  `email_aprovacao_enviado_em` datetime DEFAULT NULL,
  `cidade` varchar(100) NOT NULL DEFAULT 'Brasil',
  `estado` char(2) DEFAULT NULL,
  `descricao` text DEFAULT NULL,
  `pix_chave` varchar(20) NOT NULL,
  `cor_tema` varchar(7) DEFAULT NULL,
  `criado_em` datetime NOT NULL DEFAULT current_timestamp(),
  `foto_perfil` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cnpj` (`cnpj`),
  UNIQUE KEY `email` (`email`),
  KEY `idx_usuarios_status_cidade` (`status`,`cidade`),
  KEY `idx_usuarios_status_area` (`status`,`area`),
  KEY `fk_usuarios_admin` (`verificado_por`),
  CONSTRAINT `fk_usuarios_admin` FOREIGN KEY (`verificado_por`) REFERENCES `admins` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=402 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
